def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in range(10) if all(x == v for row in grid for x in row) is False) if False else None

    # Find the full-width and full-height separator lines.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]

    # The most common non-separator color is the background.
    sep_colors = {grid[r][0] for r in sep_rows}
    sep_colors |= {grid[0][c] for c in sep_cols}
    counts = [0] * 10
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in sep_colors:
                counts[grid[r][c]] += 1
    background = max(range(10), key=lambda x: counts[x])

    out = []
    for ri in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
        row_out = []
        for ci in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            marks = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            row_out.append(1 if marks == 2 else background)
        out.append(row_out)
    return out
